# Machine-assisted French drafts (need native review).
T = {
'firstaid.cpr': ['RCP chez l\'adulte', 'RCP avec les mains seules pour un adulte inconscient qui ne respire pas normalement.', 'Appelez d\'abord les secours. Ne vous arrêtez pas avant l\'arrivée des secours ou d\'un DAE.',
  ['Vérifiez que les lieux sont sûrs. Secouez les épaules et appelez.', 'Appelez les secours ou demandez à quelqu\'un de le faire.', 'Placez les mains au centre de la poitrine.', 'Appuyez fort et vite : 100 à 120 par minute.', 'Enfoncez d\'environ 5 cm. Laissez le thorax remonter.', 'Continuez. Utilisez un DAE s\'il arrive.'],
  ['S\'arrêter trop souvent pour vérifier.', 'Appuyer trop doucement ou trop lentement.', 'S\'appuyer sur la poitrine entre les compressions.'],
  ['La RCP avec les mains seules est une recommandation courante pour les non-formés.', 'Les enfants et les bébés demandent une autre technique : suivez la formation locale.', 'Changer de secouriste toutes les 2 minutes réduit la fatigue.']],
'firstaid.choking': ['Étouffement', 'Adulte conscient qui ne peut ni tousser, ni parler, ni respirer.', 'Si la personne perd connaissance, appelez les secours et commencez la RCP.',
  ['Demandez : « Vous étouffez ? » Encouragez à tousser fort.', 'Si elle ne peut ni respirer ni parler, appelez à l\'aide.', 'Donnez 5 tapes fermes dans le dos, entre les omoplates.', 'Puis faites 5 compressions abdominales au-dessus du nombril.', 'Alternez 5 et 5 jusqu\'à ce que cela sorte ou qu\'elle s\'effondre.'],
  ['Frapper le dos de quelqu\'un qui tousse bien.', 'Fouiller la bouche avec les doigts à l\'aveugle.', 'Donner de l\'eau à une personne qui s\'étouffe.'],
  ['Les bébés, les femmes enceintes et les personnes très corpulentes demandent une autre position des mains : suivez la formation locale.', 'Consultez un médecin ensuite, même si l\'objet est sorti.']],
'firstaid.bleeding': ['Arrêter une hémorragie grave', 'Arrêtez une hémorragie importante par une pression directe ferme.', 'Appelez les secours en cas d\'hémorragie importante. Utilisez des gants ou une barrière si possible.',
  ['Appelez les secours ou envoyez quelqu\'un le faire.', 'Appuyez fort sur la plaie avec un linge propre.', 'Ne soulevez pas le linge. Ajoutez-en dessus.', 'Continuez à appuyer sans relâche jusqu\'à l\'arrivée des secours.', 'Allongez la personne et gardez-la au chaud.'],
  ['Retirer le linge pour regarder.', 'Appuyer trop légèrement.', 'Poser un garrot sans formation sur une plaie légère.'],
  ['Un garrot peut être nécessaire pour une hémorragie de membre mortelle que la pression n\'arrête pas. Il demande une formation.', 'Ne retirez pas les objets plantés dans la plaie.']],
'firstaid.burns': ['Brûlures', 'Refroidissez la brûlure et protégez-la.', 'Les brûlures étendues, au visage, aux mains, aux parties génitales, chimiques ou électriques demandent des soins urgents.',
  ['Éloignez-vous de la source de chaleur en sécurité.', 'Refroidissez sous l\'eau courante fraîche pendant 20 minutes.', 'Retirez bagues et vêtements amples. Laissez ce qui adhère.', 'Couvrez sans serrer avec un pansement propre non adhérent.', 'Consultez si elle est grande, profonde ou en zone à risque.'],
  ['Utiliser de la glace, du beurre ou du dentifrice.', 'Percer les cloques.', 'Arracher les vêtements collés à la peau.'],
  ['Gardez le reste du corps au chaud pendant que vous refroidissez une grande brûlure.']],
'firstaid.fracture': ['Fractures et attelles simples', 'Gardez immobile un os qui semble cassé jusqu\'à l\'arrivée des secours.', 'N\'essayez pas de remettre l\'os droit. Appelez les secours pour le cou, le dos, la tête ou un os qui perce la peau.',
  ['Gardez la personne immobile. Ne bougez pas cou ni dos.', 'Contrôlez le saignement par une pression douce autour.', 'Soutenez le membre dans la position où il se trouve.', 'Immobilisez avec un matériau ferme, rembourré, au-dessus et au-dessous.', 'Vérifiez sensibilité et couleur au-delà de l\'attelle. Consultez.'],
  ['Remettre le membre droit.', 'Serrer trop l\'attelle.', 'Laisser la personne marcher dessus.'],
  ['De la glace enveloppée dans un linge peut réduire douleur et gonflement.']],
'firstaid.shock': ['Choc', 'Signes : peau pâle, froide et moite, pouls rapide et faible, confusion.', 'Le choc peut menacer la vie. Appelez les secours.',
  ['Appelez les secours.', 'Allongez la personne. Traitez tout saignement.', 'Gardez-la au chaud avec un manteau ou une couverture.', 'Ne donnez ni nourriture ni boisson.', 'Restez avec elle et surveillez la respiration.'],
  ['Donner à manger ou à boire.', 'Déplacer la personne sans nécessité.', 'La laisser seule.'],
  ['Surélever les jambes est parfois conseillé s\'il n\'y a pas de blessure aux jambes, à la tête, au cou ou au dos : suivez la formation locale.']],
'firstaid.hypothermia': ['Hypothermie et froid extrême', 'La température du corps baisse à cause du froid : frissons, confusion, élocution pâteuse.', 'Les cas graves (plus de frissons, somnolence, inconscience) exigent les secours. Manipulez avec douceur.',
  ['Mettez la personne à l\'abri du vent et de la pluie.', 'Retirez les vêtements mouillés. Séchez doucement.', 'Isolez du sol. Enveloppez de couvertures.', 'Couvrez la tête et le cou.', 'Si éveillée, donnez une boisson chaude et sucrée. Appelez à l\'aide.'],
  ['Frotter la peau.', 'Donner de l\'alcool.', 'Utiliser de l\'eau très chaude ou une chaleur directe.'],
  ['Réchauffez d\'abord le tronc. Déplacez la personne avec douceur.']],
'firstaid.heat': ['Coup de chaleur et chaleur extrême', 'Épuisement par la chaleur et coup de chaleur.', 'Confusion, malaise ou peau chaude et sèche peuvent indiquer un coup de chaleur : appelez les secours immédiatement.',
  ['Amenez la personne à l\'ombre ou dans un endroit frais.', 'Retirez les vêtements en trop.', 'Rafraîchissez la peau avec de l\'eau et en éventant.', 'Si elle est éveillée, donnez de petites gorgées d\'eau fraîche.', 'Appelez les secours si confusion ou pas d\'amélioration.'],
  ['Donner à boire à quelqu\'un qui n\'est pas bien éveillé.', 'Laisser la personne dans la chaleur.', 'Utiliser des bains glacés sans conseil.'],
  ['Les enfants et les personnes âgées surchauffent plus vite.']],
'firstaid.bites': ['Morsures et piqûres', 'Morsures et piqûres d\'animaux, de serpents et d\'insectes.', 'Difficulté à respirer, gonflement du visage ou de la gorge, ou morsure de serpent venimeux : urgence, appelez immédiatement.',
  ['Éloignez-vous de l\'animal ou de l\'insecte.', 'Restez calme. Gardez le membre touché immobile.', 'Retirez bagues et vêtements serrés près de la morsure.', 'Lavez les plaies légères à l\'eau propre et au savon.', 'Consultez. Appelez les secours si c\'est grave.'],
  ['Inciser la morsure ou aspirer le venin.', 'Poser un garrot serré.', 'Essayer d\'attraper l\'animal.'],
  ['Notez l\'heure et l\'aspect de l\'animal si c\'est sans danger.']],
'water.find': ['Eau : où la trouver', 'Où trouver de l\'eau quand le robinet est à sec.', 'Toute eau trouvée dehors peut contenir des germes ou des produits chimiques. Traitez-la avant de boire. L\'eau de mer n\'est pas potable.',
  ['Vérifiez le ballon d\'eau chaude et le réservoir de la chasse d\'eau.', 'Récupérez la pluie avec des draps et récipients propres.', 'Cherchez des ruisseaux courants, sources ou puits.', 'Évitez l\'eau qui sent le carburant, mousse ou contient des cadavres.', 'Filtrez puis désinfectez toute eau trouvée.'],
  ['Boire une eau claire sans la traiter.', 'Boire de l\'eau de mer.', 'Utiliser de l\'eau près d\'égouts ou de champs.'],
  ['L\'eau courante est en général plus sûre que l\'eau stagnante, mais elle doit aussi être traitée.']],
'water.disinfect': ['Eau : ébullition, chlore et SODIS', 'Rendez l\'eau trouvée ou filtrée plus sûre à boire.', 'Ne retire ni produits chimiques ni carburant. Si l\'eau sent le chimique, trouvez une autre source.',
  ['Filtrez d\'abord l\'eau trouble.', 'Faites bouillir à gros bouillons pendant 1 minute.', 'Au-dessus de 2 000 m, faites bouillir 3 minutes.', 'Ou ajoutez du chlore selon la notice. Attendez 30 minutes.', 'Ou remplissez des bouteilles PET claires et exposez au soleil.'],
  ['Sauter la désinfection après la filtration.', 'Utiliser de l\'eau de Javel parfumée ou avec additifs.', 'Ne pas attendre le temps de contact complet.'],
  ['Désinfection solaire (SODIS) : bouteille PET transparente en plein soleil environ 6 heures, ou 2 jours si nuageux.', 'Utilisez le calculateur de chlore dans Préparer et l\'étiquette du produit.']],
'water.store': ['Stocker l\'eau en sécurité', 'Gardez l\'eau traitée potable pour plus tard.', 'Ne stockez jamais l\'eau dans des récipients ayant contenu des produits chimiques, du carburant ou des pesticides.',
  ['Utilisez des récipients propres, alimentaires, à couvercle étanche.', 'Remplissez d\'eau traitée. Fermez bien.', 'Étiquetez avec la date.', 'Rangez au frais et à l\'obscurité, loin du carburant.', 'Renouvelez régulièrement l\'eau stockée.'],
  ['Réutiliser des récipients ayant contenu des produits chimiques.', 'Laisser les récipients ouverts.', 'Stocker près du carburant ou au soleil.'],
  ['Lavez les récipients au savon et rincez bien avant de remplir.']],
'scenario.blackout': ['Panne de courant : les 72 premières heures', 'Plus d\'électricité. Restez en sécurité, économisez la batterie et gérez nourriture et eau.', 'N\'utilisez jamais groupe électrogène, barbecue ou réchaud à l\'intérieur : le monoxyde de carbone peut tuer.',
  ['Vérifiez si seul votre logement est sans courant.', 'Utilisez des lampes torches, pas des bougies.', 'Débranchez les appareils sensibles.', 'Gardez fermés le réfrigérateur et le congélateur.', 'Économisez la batterie du téléphone : moins de luminosité, fermez les applis.'],
  ['Laisser des bougies sans surveillance.', 'Cuisiner ou chauffer à l\'intérieur avec des brûleurs à combustible.', 'Ouvrir le réfrigérateur sans cesse.'],
  ['Prenez des nouvelles des voisins âgés ou malades.', 'Gardez une radio à piles ou à manivelle pour les informations.']],
'scenario.storm': ['Tempête et vent fort', 'Vent fort, pluie et foudre.', 'Dehors, ne vous abritez jamais sous un arbre isolé. Éloignez-vous de l\'eau et du métal pendant la foudre.',
  ['Rentrez. Éloignez-vous des fenêtres.', 'Débranchez l\'électronique. Évitez la plomberie.', 'Fixez ou rentrez les objets mobiles si c\'est sûr.', 'Comptez les secondes entre l\'éclair et le tonnerre.', 'Moins de 30 secondes : mettez-vous à l\'abri. Attendez 30 minutes après.'],
  ['Se tenir sous un arbre isolé.', 'Rester en terrain découvert ou dans l\'eau.', 'Conduire sur des routes inondées.'],
  ['Une voiture fermée est un abri relativement sûr : évitez de toucher les parties métalliques.']],
'scenario.flood': ['Inondation : que faire', 'L\'eau monte. Partez tôt ; n\'attendez pas qu\'elle vous atteigne.', 'Ne marchez ni ne conduisez jamais dans l\'eau d\'une inondation. Éloignez-vous des lignes électriques tombées.',
  ['Montez tout de suite en hauteur. Suivez les consignes officielles.', 'Ne marchez ni ne conduisez dans l\'eau de crue.', 'Si c\'est sûr et sec, coupez le courant au disjoncteur général.', 'Prenez papiers, médicaments, téléphone et eau.', 'Si bloqué, appelez les secours. Montez au point le plus haut.'],
  ['Conduire sur des routes inondées.', 'Toucher des appareils électriques en étant mouillé.', 'Attendre de voir si l\'eau monte.'],
  ['L\'eau de crue peut contenir des eaux usées et des produits chimiques. Lavez-vous bien et ne la buvez pas.']],
'scenario.house-fire': ['Incendie à la maison', 'Feu dans le logement. Sortir vivant est le seul objectif.', 'Ne retournez pas à l\'intérieur pour des affaires, des animaux ou quoi que ce soit.',
  ['Criez pour alerter tout le monde. Sortez immédiatement.', 'Restez bas sous la fumée. Fermez les portes derrière vous.', 'N\'utilisez pas l\'ascenseur.', 'Appelez les secours depuis l\'extérieur.', 'Si vos vêtements prennent feu : arrêtez, couchez-vous, couvrez le visage, roulez.'],
  ['Retourner à l\'intérieur.', 'Se cacher dans un placard ou sous un lit.', 'Ouvrir une porte chaude.'],
  ['Testez la porte avec le dos de la main avant d\'ouvrir.', 'Convenez d\'un point de rassemblement familial à l\'extérieur.']],
'scenario.heatwave': ['Vague de chaleur', 'Plusieurs jours de chaleur dangereuse.', 'Ne laissez jamais une personne ou un animal dans une voiture garée. Confusion ou malaise exigent les secours.',
  ['Restez dans la pièce la plus fraîche du logement.', 'Buvez de l\'eau régulièrement, même sans soif.', 'Portez des vêtements légers et amples. Évitez l\'effort à midi.', 'Rafraîchissez la peau avec des linges humides ou une douche tiède.', 'Prenez des nouvelles des aînés, enfants et malades.'],
  ['Faire un effort intense à midi.', 'Attendre d\'avoir soif pour boire.', 'Laisser quelqu\'un dans une voiture garée.'],
  ['Fermez les rideaux des fenêtres ensoleillées. Aérez la nuit.']],
'scenario.coldwave': ['Vague de froid', 'Plusieurs jours de froid dangereux.', 'N\'utilisez jamais barbecue, réchaud ou chauffage d\'extérieur à l\'intérieur : le monoxyde de carbone peut tuer.',
  ['Restez à l\'intérieur. Choisissez une pièce à garder chaude.', 'Portez plusieurs couches et un bonnet. Gardez les vêtements secs.', 'Bouchez les courants d\'air sous les portes et fenêtres.', 'Buvez chaud et mangez régulièrement.', 'Prenez des nouvelles des aînés, bébés et malades.'],
  ['Utiliser des brûleurs sans ventilation à l\'intérieur.', 'Porter des vêtements mouillés.', 'Boire de l\'alcool pour avoir chaud.'],
  ['Frissons, confusion ou élocution pâteuse peuvent indiquer une hypothermie.']],
'scenario.earthquake': ['Séisme : que faire', 'Le sol tremble. Agissez pendant la secousse ; préparez-vous avant.', 'Ne courez pas dehors pendant la secousse. Sortez aussitôt si vous sentez le gaz.',
  ['Mettez-vous à genoux, mains au sol.', 'Protégez tête et cou sous une table solide.', 'Tenez bon jusqu\'à la fin de la secousse.', 'Dehors, allez en terrain dégagé loin des bâtiments.', 'Attendez des répliques. Vérifiez blessés et fuites de gaz.'],
  ['Courir dehors pendant la secousse.', 'Rester dans l\'encadrement d\'une porte.', 'Utiliser l\'ascenseur.'],
  ['Au volant, arrêtez-vous en zone dégagée et restez dans la voiture.', 'Éloignez-vous des fenêtres et des meubles lourds.']],
'scenario.lost': ['Perdu dans la nature : la règle STOP', 'Perdu en plein air. Appliquez la règle STOP : Stop, Think, Observe, Plan.', 'Ne continuez pas à marcher par panique. Si vous avez prévenu de votre itinéraire, rester sur place aide souvent les secours.',
  ['Arrêtez-vous. Asseyez-vous et respirez.', 'Réfléchissez. Ne bougez pas par panique.', 'Observez : environnement, eau, météo, lumière restante.', 'Planifiez : en général, restez sur place et soyez visible.', 'Appelez à l\'aide : trois coups de sifflet ou objets très colorés.'],
  ['Marcher sans plan.', 'Séparer le groupe.', 'Partir sans prévenir personne de l\'itinéraire.'],
  ['Protégez-vous du froid, de la chaleur et de la pluie avant la nuit.', 'Rationnez l\'eau. Évitez de boire de l\'eau non traitée.']],
'prepare.kit72': ['Kit de 72 heures', 'Utilisez la liste interactive dans Préparer.', '', [], [], ['Indiquez personnes et jours dans la liste ; les quantités sont provisoires en attendant la relecture.']],
'prepare.kit-car': ['Kit voiture', 'Utilisez la liste interactive dans Préparer.', '', [], [], ['Les quantités sont provisoires en attendant la relecture.']],
'shelter.camp-setup': ['Comment choisir et installer un campement', 'Choisissez l\'emplacement, montez la tente et organisez cuisine et toilettes en sécurité.', 'Les règles des parcs et zones protégées varient. Vérifiez les règles locales, les autorisations nécessaires et les interdictions de feu.',
  ['Arrivez avec au moins 2 heures de jour devant vous.', 'Choisissez un sol plat, ferme, bien drainé et légèrement surélevé.', 'Éloignez-vous des branches sèches et des arbres morts.', 'Campez à environ 60 mètres des rivières et lacs.', 'Évitez rivières à sec, fonds de vallée et pieds de pente.', 'Dégagez pierres et branches. Étendez une bâche de sol.', 'Montez la tente avec l\'entrée dos au vent.', 'Cuisinez et rangez la nourriture à 30 m de la tente.', 'Creusez les toilettes à 60 m de l\'eau et du sentier.', 'Avant de dormir, gardez lampe et chaussures toujours au même endroit.'],
  ['Monter la tente au coucher du soleil, sans temps pour corriger.', 'Camper sous un arbre mort ou isolé.', 'Cuisiner ou ranger la nourriture dans la tente.', 'Planter la tente dans un lit de rivière à sec.', 'Laisser un feu sans surveillance.', 'Ne pas convenir avec le groupe d\'un point de rassemblement et d\'un signal d\'urgence.'],
  ['Vent : installez-vous avec le côté le plus bas et étroit face au vent et utilisez tous les haubans.', 'Pluie : pente pour évacuer l\'eau et petite rigole, si c\'est permis, sans abîmer le terrain.', 'Chaleur : ombre, ventilation croisée et eau. Ne dormez jamais dans une voiture fermée au soleil.', 'Froid : le sol vole plus de chaleur que l\'air. Isolez dessous et superposez les couches.', 'Foudre : si le tonnerre suit l\'éclair en moins de 30 secondes, abritez-vous. Attendez 30 minutes après le dernier tonnerre.', 'Feu : seulement là où c\'est permis. Éteignez à l\'eau jusqu\'à ce que la cendre soit froide au toucher.'],
  ['Tente', 'Piquets et cordes', 'Bâche de sol', 'Sac de couchage', 'Lampe torche', 'Récipient d\'eau', 'Petite pelle', 'Sacs poubelle'], ['camping', 'tente', 'campement', 'nature']],
'water.diy-filter': ['Comment fabriquer un filtre à eau maison', 'Filtre en couches avec une bouteille PET. Désinfectez toujours l\'eau après filtration.', 'Si l\'eau sent fortement le carburant, les égouts ou les produits chimiques, trouvez une autre source. Si quelqu\'un a diarrhée, fièvre ou vomissements après avoir bu une eau suspecte, consultez.',
  ['Laissez l\'eau sale décanter 2 heures. Prenez celle du dessus.', 'Coupez le fond de la bouteille PET. Percez le bouchon.', 'Mettez un linge propre ou un filtre à café dans le goulot.', 'Empilez : charbon, sable fin, sable grossier, gravier.', 'Rincez le filtre à l\'eau propre jusqu\'à ce qu\'elle soit claire. Jetez-la.', 'Versez l\'eau sale lentement. Recueillez l\'eau filtrée.', 'Désinfectez : 1 minute d\'ébullition, 3 minutes au-dessus de 2 000 m.', 'Conservez dans un récipient propre et fermé.'],
  ['Croire que l\'eau est sûre parce qu\'elle est claire.', 'Utiliser du charbon de barbecue avec additifs ou des briquettes.', 'Ne pas laver d\'abord le sable et le charbon.', 'Utiliser des récipients et linges sales.', 'Inverser l\'ordre des couches ou verser trop vite.', 'Garder le filtre trop longtemps sans changer les couches.'],
  ['Le filtre retire saletés, feuilles, turbidité et une partie des plus gros parasites, mais ne garantit pas l\'élimination des bactéries, virus ou produits chimiques.', 'C\'est pourquoi la désinfection après filtration est une étape obligatoire, pas un extra.', 'Les filtres du commerce à pores de 0,1 à 0,2 micron retiennent bactéries et protozoaires, mais les virus demandent encore une désinfection.', 'L\'eau trouble gêne aussi le chlore et la désinfection solaire : filtrer d\'abord l\'améliore.', 'Les eaux d\'égout, industrielles, agricoles et l\'eau de mer ne doivent pas être traitées avec un filtre maison.'],
  ['Bouteille PET de 2 L', 'Ciseaux ou couteau', 'Linge propre ou filtre à café', 'Charbon de bois (sans additifs)', 'Sable fin lavé', 'Sable grossier lavé', 'Gravier', 'Récipient propre', 'Casserole et feu', 'Pastilles de chlore'], ['eau', 'filtre', 'purification', 'bouteille', 'pet']],
}
